const uploadProgress = document.querySelector('vl-upload-progress');

// De knoppen Opnieuw proberen (retryable) en Annuleren (cancellable) vuren deze events af; event.detail bevat
// filename en target (het element zelf).
uploadProgress.addEventListener('vl-upload-progress-retry', (event) => {
    console.log('opnieuw proberen', event.detail.filename);
});
uploadProgress.addEventListener('vl-upload-progress-cancel', (event) => {
    console.log('annuleren', event.detail.filename);
});
